require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/ManagementMeetingsRepository.php';Auth::requireLogin();$u=Auth::user();$id=(int)($_GET['id']??$_POST['id']??0);$d=ManagementMeetingsRepository::getDecisionById($id,$u);if(!$d){http_response_code(404);exit('مصوبه در دسترس نیست.');}if(!ManagementMeetingsRepository::canEditDecision($d,$u)){http_response_code(403);exit('دسترسی غیرمجاز');}if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');ManagementMeetingsRepository::updateDecision($id,$_POST,(int)$u['id']);flash('مصوبه بروزرسانی شد.');redirect('/admin/management-decision-view.php?id='.$id);}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Decision edit: '.$e->getMessage());flash('ویرایش مصوبه انجام نشد.','danger');}redirect('/admin/management-decision-edit.php?id='.$id);}$users=ManagementMeetingsRepository::users();$units=ManagementMeetingsRepository::units();$pageTitle='ویرایش مصوبه';$adminExtraStylesheets=['/assets/css/management-governance.css'];require __DIR__.'/../views/partials/admin-header.php';?>
